={
  "model": "openai/gpt-oss-20b",
  "messages": [
    {
      "role": "system",
      "content": "You are a professional logistics operations analyst. Generate clean plain-text business emails only. Do not use markdown symbols like *, **, bullets, or hashtags. Use INR currency symbol ₹ instead of $. Keep formatting simple and professional."
    },
    {
      "role": "user",
      "content": "Create a professional daily logistics operations email report using these metrics: Total Shipments: {{$json.total_shipments_created}}, Delivered: {{$json.delivered_shipments}}, Not Delivered: {{$json.not_delivered_shipments}}, Domestic: {{$json.domestic_shipments}}, International: {{$json.international_shipments}}, Express: {{$json.express_shipments}}, Regular: {{$json.regular_shipments}}, Total Charges: ₹{{$json.total_shipment_charges_collected}}, Pending Payments: {{$json.pending_payments_count}}. Highlight any delays or payment issues and end with one actionable recommendation."
    }
  ],
  "temperature": 0.4
}
